-- SQLite does not support ALTER TABLE to add CHECK constraints to existing columns.
-- To add a CHECK constraint, we must rebuild the table.

-- 1. Start a transaction to ensure atomicity
BEGIN TRANSACTION;

-- 2. Create a new table with the desired constraint
CREATE TABLE accounts_new (
    id INTEGER PRIMARY KEY,
    balance INTEGER NOT NULL CHECK (balance >= 0)
);

-- 3. Copy the existing data into the new table
-- (Existing data is valid, so this will succeed)
INSERT INTO accounts_new (id, balance)
SELECT id, balance FROM accounts;

-- 4. Drop the old table
DROP TABLE accounts;

-- 5. Rename the new table to the original name
ALTER TABLE accounts_new RENAME TO accounts;

COMMIT;
