import csv
import io

def solve(raw):
    # Use io.StringIO to treat the string as a file for the csv module
    f = io.StringIO(raw.strip())
    reader = csv.DictReader(f)

    # Dictionary to store list of valid salaries per department
    dept_salaries = {}

    for row in reader:
        # Extract and strip fields
        dept = row.get('dept', '').strip()
        salary_str = row.get('salary', '').strip()

        # Skip if department is empty (optional, but good practice)
        if not dept:
            continue

        # Try to convert salary to float
        try:
            salary_val = float(salary_str)

            if dept not in dept_salaries:
                dept_salaries[dept] = []
            dept_salaries[dept].append(salary_val)
        except ValueError:
            # Skip rows where salary is blank or not a valid number
            continue

    # Calculate averages
    result = {}
    for dept, salaries in dept_salaries.items():
        if salaries:
            avg = sum(salaries) / len(salaries)
            result[dept] = round(avg, 2)

    return result
