import json

def solve(text):
    records = []
    errors = 0

    # Split by newline and iterate through lines
    for line in text.splitlines():
        # Strip whitespace to check for blank lines
        stripped_line = line.strip()

        # Skip blank lines
        if not stripped_line:
            continue

        try:
            # Attempt to parse the line as JSON
            data = json.loads(stripped_line)

            # Check if it is a dictionary and contains the 'id' key
            if isinstance(data, dict) and 'id' in data:
                records.append(data)
            else:
                errors += 1
        except (json.JSONDecodeError, TypeError):
            # If parsing fails or data is not a valid JSON type
            errors += 1

    return {
        'records': records,
        'errors': errors
    }
