from datetime import datetime, timedelta

def solve(text):
    # Dictionary to store list of timestamps per user
    user_events = {}

    lines = text.strip().split('\n')
    if not lines or (len(lines) == 1 and not lines[0]):
        return {}

    for line in lines:
        parts = line.split()
        # Ignore lines that do not have exactly 3 whitespace-separated fields
        if len(parts) != 3:
            continue

        timestamp_str, user, action = parts

        try:
            # Parse ISO timestamp
            dt = datetime.fromisoformat(timestamp_str)

            if user not in user_events:
                user_events[user] = []
            user_events[user].append(dt)
        except ValueError:
            # Ignore lines with invalid timestamps
            continue

    result = {}
    for user, timestamps in user_events.items():
        # Sort events by timestamp
        timestamps.sort()

        if not timestamps:
            continue

        sessions = 1
        for i in range(1, len(timestamps)):
            # A new session starts if gap to previous event is strictly more than 30 minutes
            if timestamps[i] - timestamps[i-1] > timedelta(minutes=30):
                sessions += 1

        result[user] = sessions

    return result
