import csv
import io

def solve(raw):
    # Use io.StringIO to treat the string as a file for csv.DictReader
    f = io.StringIO(raw.strip())
    reader = csv.DictReader(f)

    # Store rows with an index to maintain stable sort for equal dates
    rows = []
    for i, row in enumerate(reader):
        rows.append({
            'date': row['date'],
            'account': row['account'],
            'amount': float(row['amount']),
            'type': row['type'],
            'index': i
        })

    # Sort by date ascending, then by original index to keep file order
    rows.sort(key=lambda x: (x['date'], x['index']))

    # State tracking for each account
    # accounts[name] = {'balance': float, 'overdrawn_on': str or None}
    accounts = {}

    for row in rows:
        acc = row['account']
        amount = row['amount']
        date = row['date']

        if acc not in accounts:
            accounts[acc] = {'balance': 0.0, 'overdrawn_on': None}

        # Update balance
        if row['type'] == 'credit':
            accounts[acc]['balance'] += amount
        else:
            accounts[acc]['balance'] -= amount

        # Check for first instance of overdrawn status
        # We use a small epsilon for float comparison if necessary, 
        # but standard float is fine for 2 decimal precision here.
        if accounts[acc]['balance'] < 0 and accounts[acc]['overdrawn_on'] is None:
            accounts[acc]['overdrawn_on'] = date

    # Final pass to round balances to 2 decimals
    for acc in accounts:
        accounts[acc]['balance'] = round(accounts[acc]['balance'], 2)

    return accounts
